let work = employees
  .filter(e => e.name === 'Ольга Орлова')
  .map(e => ({ ...e, level: 0 }));                  // якорь
const result = [...work];

while (work.length > 0) {                          // пустой шаг — конец
  const prev = new Map(work.map(s => [s.id, s.level]));
  work = employees
    .filter(e => prev.has(e.manager_id))           // JOIN subordinates s ON e.manager_id = s.id
    .map(e => ({ ...e, level: prev.get(e.manager_id) + 1 }));
  result.push(...work);                            // UNION ALL
}

