/** Любой объект Drizzle, который выполняет запросы: база или транзакция. */
export type Executor = Pick<
  NodePgDatabase<Record<string, unknown>>,
  'execute' | 'insert' | 'select' | 'update' | 'delete'
>;

// внутри ProgressService (упрощённо)
private async touch(tx: Executor, userId: string, bookId: string, now: Date) {
  await tx.update(readerProgress)
    .set({ lastActiveAt: now })
    .where(and(eq(readerProgress.userId, userId), eq(readerProgress.bookId, bookId)));
}

import { defineConfig } from 'drizzle-kit';

export default defineConfig({
  dialect: 'postgresql',
  schema: './src/db/schema.ts',   // откуда читать таблицы
  out: './drizzle',               // куда класть SQL-миграции
  dbCredentials: { url: process.env.DATABASE_URL ?? '' },
  strict: true,
});

/** Применяет SQL-миграции drizzle-kit через одно выделенное соединение. */
export async function runMigrations(url: string, migrationsFolder: string) {
  const client = new pg.Client({ connectionString: url });
  await client.connect();
  try {
    await migrate(drizzle({ client }), { migrationsFolder });
  } finally {
    await client.end();
  }
}

